#include "ibm.hpp"

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

// A frozen-configuration, finite-periodic-domain creeping-flow probe. The
// velocity amplitude is prescribed, not generated by a particle force. This
// measures the current IBM response; no lubrication/contact model is added.
namespace {
using namespace ibdem;
using Clock=std::chrono::steady_clock;

struct Options {
    double radius=8.0,gap=1.0,speed=1.0e-5,nu=.3,retraction=0.0;
    int steps=2000;
    std::string motion="normal",mode="fast",output;
};

double number(const std::string& s){
    std::size_t used=0;double x=std::stod(s,&used);
    if(used!=s.size()||!std::isfinite(x))throw std::invalid_argument("Expected a finite numeric option");
    return x;
}
int integer(const std::string& s){
    std::size_t used=0;int x=std::stoi(s,&used);
    if(used!=s.size())throw std::invalid_argument("Expected an integer option");
    return x;
}

// The six entries are force x/y and torque ABOUT EACH BODY CENTER. Angular
// impulses exported by IBM are first converted from the fixed global origin.
using Loads=std::array<double,6>;
Loads loads(const IBM& ib,const std::vector<Body>& b){
    Loads result{};
    if(ib.hydrodynamic_impulse.size()!=2)throw std::runtime_error("Missing prescribed-body impulses");
    for(int i=0;i<2;++i){const auto& h=ib.hydrodynamic_impulse[i];
        result[3*i]=h.linear.x;result[3*i+1]=h.linear.y;
        result[3*i+2]=h.angular-cross(b[i].x,h.linear);
    }
    // Each LBM step has dt=1, so the integrated impulses equal the average
    // forces/torques over that step in the prototype's lattice units.
    return result;
}

double scaled_norm(const Loads& f,double radius){
    double s=0;for(int i=0;i<6;++i){double value=f[i]/(i%3==2?radius:1.0);s+=value*value;}
    return std::sqrt(s);
}
Loads mean(const std::vector<Loads>& history,std::size_t first,std::size_t end){
    Loads result{};for(std::size_t i=first;i<end;++i)for(int j=0;j<6;++j)result[j]+=history[i][j];
    const double count=double(end-first);for(auto& x:result)x/=count;return result;
}
double power(const Loads& f,const std::vector<Body>& b){
    double value=0;for(int i=0;i<2;++i)value+=f[3*i]*b[i].v.x+f[3*i+1]*b[i].v.y+f[3*i+2]*b[i].omega;
    return value;
}
void write_loads(const Loads& f){
    std::cout<<"[{\"force\":["<<f[0]<<','<<f[1]<<"],\"torque_center\":"<<f[2]
             <<"},{\"force\":["<<f[3]<<','<<f[4]<<"],\"torque_center\":"<<f[5]<<"}]";
}
}

int main(int argc,char** argv){
    try{
        Options options;
        for(int i=1;i<argc;++i){const std::string key=argv[i];
            if(key=="--help"){
                std::cout<<"resistance --radius R --gap h --motion normal|slide|spin_same|spin_opposite\n"
                         <<"           --steps N --speed V --nu NU [--retraction RSHIFT] [--output CSV] [--mode fast|ref]\n"
                         <<"Defaults: R=8, h=1, N=2000, V=1e-5, nu=0.3, normal, fast.\n"
                         <<"Normal/slide prescribe relative speed V; spin modes use |omega|=V/R.\n"
                         <<"Frozen geometry, approximately 10R x 8R periodic box, no near-field model.\n"
                         <<"Optional numerical marker retraction defaults to zero; physical radius/gap are unchanged.\n"
                         <<"Reported modal resistance is minus hydrodynamic power divided by V^2.\n"
                         <<"Leading small-gap cylinder asymptotes are diagnostics, not exact full-domain values.\n";
                return 0;
            }
            if(i+1>=argc)throw std::invalid_argument("Missing value for "+key);
            const std::string value=argv[++i];
            if(key=="--radius")options.radius=number(value);
            else if(key=="--gap")options.gap=number(value);
            else if(key=="--speed")options.speed=number(value);
            else if(key=="--nu")options.nu=number(value);
            else if(key=="--retraction")options.retraction=number(value);
            else if(key=="--steps")options.steps=integer(value);
            else if(key=="--motion")options.motion=value;
            else if(key=="--mode")options.mode=value;
            else if(key=="--output")options.output=value;
            else throw std::invalid_argument("Unknown option: "+key);
        }
        if(!(options.radius>=2.0&&options.gap>0.0&&options.speed>0.0&&options.nu>0.0)||options.steps<4)
            throw std::invalid_argument("Require radius>=2, gap>0, speed>0, nu>0 and steps>=4");
        if(options.retraction<0.0||options.retraction>=options.radius)
            throw std::invalid_argument("Require 0 <= retraction < physical radius");
        if(options.mode!="fast"&&options.mode!="ref")throw std::invalid_argument("Mode must be fast or ref");
        if(options.motion!="normal"&&options.motion!="slide"&&options.motion!="spin_same"&&options.motion!="spin_opposite")
            throw std::invalid_argument("Unknown prescribed motion");
        const double quadratic_input=options.speed*options.speed;
        if(!(quadratic_input>0.0)||!std::isfinite(quadratic_input))
            throw std::invalid_argument("Speed squared is outside the floating-point range");
        const double nominal_Re=2*options.radius*options.speed/options.nu;
        if(!std::isfinite(nominal_Re)||nominal_Re>.1)
            throw std::invalid_argument("This creeping-flow probe requires 2*radius*speed/nu <= 0.1; reduce speed");
        const double xextent=std::ceil(std::max(10*options.radius,4*options.radius+options.gap+8));
        const double yextent=std::ceil(std::max(8*options.radius,2*options.radius+8));
        if(!std::isfinite(xextent)||!std::isfinite(yextent)||xextent>std::numeric_limits<int>::max()||yextent>std::numeric_limits<int>::max())
            throw std::invalid_argument("Requested lattice dimensions overflow");
        const int nx=static_cast<int>(xextent),ny=static_cast<int>(yextent);
        const auto started=Clock::now();
        LBM fluid(nx,ny,.5+3*options.nu);
        const Vec2 midpoint{.5*(nx-1),.5*(ny-1)};
        const double half_separation=options.radius+.5*options.gap;
        std::vector<Body> bodies{
            disk(0,{midpoint.x-half_separation,midpoint.y},options.radius,1.0,true),
            disk(1,{midpoint.x+half_separation,midpoint.y},options.radius,1.0,true)
        };
        if(!(norm(bodies[1].x-bodies[0].x)-2*options.radius>0.0))
            throw std::invalid_argument("Positive gap is not representable at the requested coordinate scale");
        if(options.motion=="normal"){bodies[0].v={.5*options.speed,0};bodies[1].v={-.5*options.speed,0};}
        else if(options.motion=="slide"){bodies[0].v={0,.5*options.speed};bodies[1].v={0,-.5*options.speed};}
        else{bodies[0].omega=options.speed/options.radius;bodies[1].omega=(options.motion=="spin_same"?1.0:-1.0)*options.speed/options.radius;}
        IBM ib(options.mode=="fast"?IBM::Mode::CachedBlocks:IBM::Mode::Reference);
        ib.relative_tolerance=1e-11;ib.absolute_tolerance=1e-14;ib.max_bodies_per_block=2;
        ib.marker_retraction=options.retraction;
        ib.initialize(fluid,bodies);
        std::ofstream csv;
        if(!options.output.empty()){
            csv.open(options.output);if(!csv)throw std::runtime_error("Cannot open CSV output");
            csv<<"step,modal_resistance,hydrodynamic_power,f0x,f0y,t0_center,f1x,f1y,t1_center,max_slip,residual,iterations,mean_ux,mean_uy\n"<<std::setprecision(17);
        }
        std::vector<Loads> history;history.reserve(options.steps);
        double min_rho=1.0,max_rho=1.0,max_slip=0.0,max_mach=0.0,max_residual=0.0;
        long long iterations=0;int max_iterations=0,rebuilds=0;
        Vec2 lattice_momentum,mean_velocity;double lattice_mass=0;
        for(int step=0;step<options.steps;++step){
            fluid.collide_stream();ib.couple_prescribed(fluid,bodies);
            const Loads f=loads(ib,bodies);for(double value:f)if(!std::isfinite(value))throw std::runtime_error("Nonfinite measured force/torque");
            history.push_back(f);lattice_momentum={};lattice_mass=0;
            for(int cell=0;cell<fluid.n;++cell){
                const double rho=fluid.rho[cell];const Vec2 u=fluid.u[cell];
                if(!(rho>0.0)||!std::isfinite(rho)||!std::isfinite(u.x)||!std::isfinite(u.y))
                    throw std::runtime_error("Nonfinite/nonpositive fluid state in resistance probe");
                min_rho=std::min(min_rho,rho);max_rho=std::max(max_rho,rho);
                const double mach=std::sqrt(3.0)*norm(u);max_mach=std::max(max_mach,mach);
                if(mach>.2)throw std::runtime_error("Resistance probe exceeded Mach 0.2; no result accepted");
                lattice_momentum+=u*rho;lattice_mass+=rho;
            }
            mean_velocity=lattice_momentum/lattice_mass;
            max_slip=std::max(max_slip,ib.stats.max_slip);max_residual=std::max(max_residual,ib.stats.residual);
            iterations+=ib.stats.iterations;max_iterations=std::max(max_iterations,ib.stats.iterations);rebuilds+=ib.stats.preconditioner_rebuilt;
            if(csv){csv<<step+1<<','<<-power(f,bodies)/quadratic_input<<','<<power(f,bodies);
                for(double value:f)csv<<','<<value;
                csv<<','<<ib.stats.max_slip<<','<<ib.stats.residual<<','<<ib.stats.iterations<<','<<mean_velocity.x<<','<<mean_velocity.y<<'\n';
            }
        }
        const std::size_t window=std::min<std::size_t>(history.size(),std::max(20,options.steps/5));
        const std::size_t begin=history.size()-window,middle=begin+window/2;
        const Loads average=mean(history,begin,history.size()),early=mean(history,begin,middle),late=mean(history,middle,history.size());
        Loads change{};for(int i=0;i<6;++i)change[i]=late[i]-early[i];
        const double force_scale=std::max(scaled_norm(average,options.radius),options.nu*options.speed);
        const double window_drift=scaled_norm(change,options.radius)/force_scale;
        const double modal_resistance=-power(average,bodies)/quadratic_input;
        double minimum_resistance=std::numeric_limits<double>::infinity(),maximum_resistance=-minimum_resistance;
        for(std::size_t i=begin;i<history.size();++i){double r=-power(history[i],bodies)/quadratic_input;minimum_resistance=std::min(minimum_resistance,r);maximum_resistance=std::max(maximum_resistance,r);}
        // Spatial inversion exchanges the bodies for normal/slide/same-spin.
        // Opposite-spin uses x-reflection instead: its lateral forces may be
        // equal, not opposite. A net mean flow is reported, never subtracted.
        const bool opposite=options.motion=="spin_opposite";
        const double symmetry_fx=average[0]+average[3];
        const double symmetry_fy=average[1]+(opposite?-1.0:1.0)*average[4];
        const double symmetry_t=average[2]+(opposite?1.0:-1.0)*average[5];
        const double symmetry_error=std::sqrt(symmetry_fx*symmetry_fx+symmetry_fy*symmetry_fy+symmetry_t*symmetry_t/(options.radius*options.radius))/force_scale;
        // Leading parallel-cylinder Reynolds-lubrication asymptotes per unit
        // out-of-plane depth. R_eff=R/2, dynamic viscosity=nu at rho_ref=1.
        // They describe singular gap terms, not the full periodic-domain drag.
        const double Rn=1.5*pi*options.nu*std::pow(options.radius/options.gap,1.5);
        const double Ct=pi*options.nu*std::sqrt(options.radius/options.gap);
        const double leading=options.motion=="normal"?Rn:(options.motion=="slide"?Ct:4*Ct);
        if(!std::isfinite(modal_resistance)||!std::isfinite(window_drift)||!std::isfinite(symmetry_error)||!std::isfinite(Rn)||!std::isfinite(Ct)||!std::isfinite(leading))
            throw std::runtime_error("Nonfinite resistance diagnostic; no result accepted");
        const double runtime=std::chrono::duration<double>(Clock::now()-started).count();
        std::cout<<std::setprecision(17)
            <<"{\"probe\":\"finite_periodic_frozen_geometry_creeping_flow\",\"mode\":\""<<options.mode<<"\",\"motion\":\""<<options.motion
            <<"\",\"near_field_model\":\"none\",\"radius\":"<<options.radius<<",\"gap\":"<<options.gap<<",\"gap_over_radius\":"<<options.gap/options.radius
            <<",\"marker_retraction\":"<<options.retraction<<",\"constraint_marker_radius\":"<<options.radius-options.retraction
            <<",\"nx\":"<<nx<<",\"ny\":"<<ny<<",\"steps\":"<<options.steps<<",\"speed\":"<<options.speed<<",\"nu\":"<<options.nu
            <<",\"rho_reference\":1,\"nominal_relative_Re\":"<<nominal_Re<<",\"markers\":"<<ib.markers.size()<<",\"quadratic_input\":"<<quadratic_input
            <<",\"resistance_definition\":\"minus_sum(F_dot_V_plus_Tcenter_times_omega)_over_speed_squared\",\"modal_resistance\":"<<modal_resistance
            <<",\"last_window_samples\":"<<window<<",\"last_window_relative_force_drift\":"<<window_drift
            <<",\"last_window_resistance_min\":"<<minimum_resistance<<",\"last_window_resistance_max\":"<<maximum_resistance
            <<",\"drift_below_one_percent\":"<<(window_drift<.01?"true":"false")
            <<",\"steady_state_caveat\":\"small_window_drift_is_evidence_not_proof_of_domain_time_convergence\",\"mean_hydrodynamic_loads\":";
        write_loads(average);std::cout<<",\"last_hydrodynamic_loads\":";write_loads(history.back());
        std::cout<<",\"mean_force_sum\":["<<average[0]+average[3]<<','<<average[1]+average[4]<<"],\"symmetry_error_relative\":"<<symmetry_error
            <<",\"symmetry_definition\":\""<<(opposite?"x_reflection_for_opposite_spin":"central_inversion")
            <<"\",\"leading_asymptotic_Rn\":"<<Rn<<",\"leading_asymptotic_Ct\":"<<Ct<<",\"leading_asymptotic_modal_resistance\":"<<leading
            <<",\"measured_to_leading_ratio\":"<<modal_resistance/leading
            <<",\"asymptotic_caveat\":\"leading_small_gap_parallel_cylinder_term_only_not_exact_full_periodic_force\",\"min_density\":"<<min_rho<<",\"max_density\":"<<max_rho
            <<",\"max_mach\":"<<max_mach<<",\"max_slip\":"<<max_slip<<",\"max_residual\":"<<max_residual
            <<",\"mean_lattice_velocity_final\":["<<mean_velocity.x<<','<<mean_velocity.y<<"],\"lattice_momentum_final\":["<<lattice_momentum.x<<','<<lattice_momentum.y
            <<"],\"iterations_total\":"<<iterations<<",\"iterations_max\":"<<max_iterations<<",\"preconditioner_rebuilds\":"<<rebuilds
            <<",\"runtime_seconds\":"<<runtime<<",\"timing_scope\":\"initialization_all_steps_diagnostics_and_optional_CSV_excludes_final_JSON\"}\n";
        return 0;
    }catch(const std::exception& e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}
}
